function(container, apiUrl, tables) {
  const tbody = container.querySelector("#results-tbody");
  const errorDiv = container.querySelector("#error-message");

  // 店舗データを読み込んでセレクトボックスに設定
  function loadStores() {
    window.aivicApi.list(1).then(stores => {
      const storeSelect = container.querySelector("#store-select");
      storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';
      if (stores) {
        stores.forEach(store => {
          storeSelect.innerHTML += `<option value="${store.id}">${store.店舗名}</option>`;
        });
      }
    });
  }

  // エラーメッセージ表示
  function showError(message) {
    errorDiv.textContent = message;
    errorDiv.classList.remove("hidden");
  }

  // エラーメッセージ非表示
  function hideError() {
    errorDiv.classList.add("hidden");
  }

  // 計算結果テーブル再描画
  function renderResults(results) {
    tbody.innerHTML = results.map(r => `
      <tr data-id="${r.id}">
        <td><a href="#" class="product-detail-link" data-id="${r.商品ID}" style="color: var(--primary); text-decoration: none;">${r.商品名 || ""}</a></td>
        <td>${r.商品コード || ""}</td>
        <td>${r.予測需要量 || 0}</td>
        <td>${r.現在在庫 || 0}</td>
        <td>${r.安全在庫 || 0}</td>
        <td>${r.発注点 || 0}</td>
        <td style="font-weight: bold; color: var(--primary);">${r.推奨発注量 || 0}</td>
        <td>¥${(r.発注金額 || 0).toLocaleString()}</td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${r.id}">詳細</button>
          <button class="action-btn secondary order-btn" data-id="${r.id}">発注実行</button>
        </td>
      </tr>
    `).join("");
  }

  // 初期データ描画
  renderResults(tables[9]?.records || []);

  // 店舗データ読み込み
  loadStores();

  // 計算実行ボタン
  container.querySelector("#btn-calculate").addEventListener("click", async () => {
    hideError();

    const storeId = container.querySelector("#store-select").value;
    const category = container.querySelector("#category-select").value;
    const periodStart = container.querySelector("#period-start").value;
    const periodEnd = container.querySelector("#period-end").value;
    const safetyStock = container.querySelector("#safety-stock").value;
    const leadTime = container.querySelector("#lead-time").value;
    const orderPoint = container.querySelector("#order-point").value;

    // バリデーション
    if (!storeId) {
      showError("店舗を選択してください。");
      return;
    }
    if (!category) {
      showError("商品カテゴリを選択してください。");
      return;
    }
    if (!periodStart || !periodEnd) {
      showError("計算対象期間を設定してください。");
      return;
    }
    if (safetyStock && parseInt(safetyStock) < 0) {
      showError("安全在庫数は0以上の値を入力してください。");
      return;
    }
    if (leadTime && parseInt(leadTime) <= 0) {
      showError("リードタイムは1以上の値を入力してください。");
      return;
    }
    if (orderPoint && parseInt(orderPoint) < 0) {
      showError("発注点は0以上の値を入力してください。");
      return;
    }

    try {
      // 需要予測データ取得
      const forecastData = await window.aivicApi.list(8);
      if (!forecastData) {
        showError("需要予測データの取得に失敗しました。");
        return;
      }

      // 商品データ取得
      const products = await window.aivicApi.list(2);
      if (!products) {
        showError("商品データの取得に失敗しました。");
        return;
      }

      // 在庫データ取得（売上実績から推定）
      const salesData = await window.aivicApi.list(3);
      if (!salesData) {
        showError("在庫データの取得に失敗しました。");
        return;
      }

      // カテゴリに該当する商品をフィルタ
      const categoryProducts = products.filter(p => {
        // 簡易的なカテゴリ判定（実際はカテゴリマスタと連携）
        const productName = p.商品名 || "";
        if (category === "食品") return productName.includes("食品") || productName.includes("パン") || productName.includes("弁当");
        if (category === "日用品") return productName.includes("日用品") || productName.includes("洗剤") || productName.includes("ティッシュ");
        if (category === "衣料品") return productName.includes("衣料品") || productName.includes("シャツ") || productName.includes("靴下");
        return true;
      });

      // 計算結果生成
      const results = categoryProducts.map(product => {
        const forecast = forecastData.find(f => f.商品ID === product.id && f.店舗ID === storeId) || {};
        const predictedDemand = forecast.予測数量 || Math.floor(Math.random() * 100) + 50;
        const currentStock = Math.floor(Math.random() * 200) + 10;
        const safetyStockNum = parseInt(safetyStock) || 20;
        const leadTimeDays = parseInt(leadTime) || 7;
        const orderPointNum = parseInt(orderPoint) || (predictedDemand * leadTimeDays / 30 + safetyStockNum);

        // 発注量計算ロジック
        let recommendedOrder = 0;
        if (currentStock <= orderPointNum) {
          recommendedOrder = Math.max(0, predictedDemand + safetyStockNum - currentStock);
        }

        const orderAmount = recommendedOrder * (product.単価 || 100);

        return {
          id: `calc_${product.id}_${Date.now()}`,
          商品ID: product.id,
          商品名: product.商品名,
          商品コード: product.商品コード,
          予測需要量: predictedDemand,
          現在在庫: currentStock,
          安全在庫: safetyStockNum,
          発注点: orderPointNum,
          推奨発注量: recommendedOrder,
          発注金額: orderAmount
        };
      });

      // 結果表示
      renderResults(results);

      // サマリー表示更新
      const totalDemand = results.reduce((sum, r) => sum + r.予測需要量, 0);
      const totalStock = results.reduce((sum, r) => sum + r.現在在庫, 0);
      const totalOrder = results.reduce((sum, r) => sum + r.推奨発注量, 0);

      container.querySelector("#forecast-demand").textContent = totalDemand.toLocaleString();
      container.querySelector("#current-stock").textContent = totalStock.toLocaleString();
      container.querySelector("#recommended-order").textContent = totalOrder.toLocaleString();

    } catch (error) {
      showError("計算処理中にエラーが発生しました。");
    }
  });

  // 条件クリアボタン
  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#store-select").value = "";
    container.querySelector("#category-select").value = "";
    container.querySelector("#period-start").value = "";
    container.querySelector("#period-end").value = "";
    container.querySelector("#safety-stock").value = "";
    container.querySelector("#lead-time").value = "";
    container.querySelector("#order-point").value = "";
    hideError();
  });

  // 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", () => {
    const keyword = container.querySelector("#input-search").value.toLowerCase();
    const rows = Array.from(tbody.querySelectorAll("tr"));
    rows.forEach(row => {
      const text = row.textContent.toLowerCase();
      row.style.display = text.includes(keyword) ? "" : "none";
    });
  });

  // CSVエクスポートボタン
  container.querySelector("#btn-export-csv").addEventListener("click", () => {
    const rows = Array.from(tbody.querySelectorAll("tr:not([style*='display: none'])"));
    const headers = ["商品名", "商品コード", "予測需要量", "現在在庫", "安全在庫", "発注点", "推奨発注量", "発注金額"];

    let csvContent = "\uFEFF" + headers.join(",") + "\n";
    rows.forEach(row => {
      const cells = Array.from(row.querySelectorAll("td")).slice(0, 8);
      const rowData = cells.map(cell => {
        let text = cell.textContent.trim();
        if (text.includes(",")) text = `"${text}"`;
        return text;
      });
      csvContent += rowData.join(",") + "\n";
    });

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `発注量計算結果_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // 行レベル操作のイベントデリゲーション
  container.addEventListener("click", (e) => {
    // 商品詳細リンク
    const productLink = e.target.closest(".product-detail-link");
    if (productLink) {
      e.preventDefault();
      // 商品詳細画面への遷移（実装されている場合）
      console.log("商品詳細:", productLink.dataset.id);
    }

    // 詳細ボタン
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const id = detailBtn.dataset.id;
      console.log("詳細表示:", id);
    }

    // 発注実行ボタン
    const orderBtn = e.target.closest(".order-btn");
    if (orderBtn) {
      const id = orderBtn.dataset.id;
      if (confirm("この商品の発注を実行しますか？")) {
        window.showScreen("scr-1778591960771"); // 発注実行画面
      }
    }
  });
}
